-- PROJECT: Customer Shopping Behavior & Segmentation Analytics
-- ANALYST: Anand Bhujbal
-- DATABASE: MySQL 8.0 (customer_behavior)
-- TOTAL RECORDS: 3,900 Transactions ($233,081 Total Revenue)
-- OBJECTIVE: 10 Strategic Business Queries, Customer Lifecycle CTEs,
--            Window Functions, and Promotional Elasticity Analysis
-- =====================================================================

SELECT * FROM customer;

-- 1. Revenue Analysis --
-- Compared total revenue generated by male and female customers

SELECT 
    gender, SUM(purchase_amount) AS total_revenue
FROM
    customer
GROUP BY gender
ORDER BY total_revenue DESC;

-- 2.  Discount & Spending Analysis --
--  Identified discount users whose purchase amount  were at or above the overall average 
SELECT 
    customer_id, purchase_amount
FROM
    customer
WHERE
    discount_applied = 'Yes'
        AND purchase_amount >= (SELECT 
            AVG(purchase_amount)
        FROM
            customer);
            
-- 3. Product Rating Analysis --
-- Ranked the top 5 products by average  review ratting 

SELECT 
    item_purchased,
    ROUND(AVG(review_rating), 2) AS 'Average product Rating'
FROM
    customer
GROUP BY item_purchased
ORDER BY AVG(review_rating) DESC
LIMIT 5;

-- 4.  Shipping Analysis --
-- Compared average purchase amount for  Standard and Express
SELECT 
    shipping_type,
    ROUND(AVG(purchase_amount), 2) AS Average_purchase
FROM
    customer
WHERE
    shipping_type IN ('Standard' , 'Express')
GROUP BY shipping_type
ORDER BY Average_purchase DESC;

-- 5. Subscription Analysis --
-- Compared customer counts,average spneding  and total revenue  between subscribers and 
-- NoN Subscribers
SELECT 
    subscription_status,
    COUNT(customer_id) AS Customer_count,
    ROUND(AVG(purchase_amount), 2) AS Average_purchase,
    SUM(purchase_amount) AS total_revenue
FROM
    customer
GROUP BY subscription_status
ORDER BY total_revenue DESC; 

-- 6.  Discount Dependency Analysis --
-- Identified the top 5 products by percentage of purchase with discount applied

SELECT 
    item_purchased,
    ROUND(100.0 * SUM(CASE
                WHEN discount_applied = 'Yes' THEN 1
                ELSE 0
            END) / COUNT(*),
            2) AS discount_rate
FROM
    customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
limit 5;

-- 7. Customer Segmentation --
-- Classified customers into New, Returning and Loyal segment based on previous purchase
with customer_type as 
(SELECT 
    customer_id,
    previous_purchases,
    CASE
        WHEN previous_purchases = 1 THEN 'New'
        WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
        ELSE 'Loyal'
    END AS customer_segment
FROM
    customer)
   SELECT 
    customer_segment, COUNT(*) AS Number_of_customers
FROM
    customer_type
GROUP BY customer_segment
ORDER BY Number_of_customers DESC;

-- 8. Product Popularity Analysi --
--  Idendified the top 3 products within each category
WITH  items_count AS (
SELECT  
    category,
    item_purchased,
    COUNT(customer_id) AS total_customer,
ROW_NUMBER()OVER(
PARTITION BY 
      category 
ORDER BY 
     COUNT(customer_id)DESC) AS category_rank
FROM customer
GROUP BY 
      category,
      item_purchased
)
SELECT 
   category,
   item_purchased,
   category_rank
FROM items_count
WHERE category_rank <=3;

-- 9. Repeate Buyers Analysis --
-- Compared Subscription Status among customers with more than 5 previous purchase.

SELECT 
    subscription_status,
    COUNT(customer_id) AS repeated_customers
FROM
    customer
WHERE
    previous_purchases > 5
GROUP BY subscription_status
ORDER BY repeated_customers;

-- 10. Age Group Analysis --
-- Compared the Age_group by Total_revenue

SELECT 
    age_group, SUM(purchase_amount) AS Total_revenue
FROM
    customer
GROUP BY age_group
ORDER BY Total_revenue DESC;  